export type ReturnResourceInput = { /** What the buyer can do with the return, in this order: withdraw, ship_items, then pay_balance. A buyer's read or change through a customer session on /v1/me, or in Flint's buyer account, lists all three every time; merchant reads and webhooks get an empty list. ship_items is required while handoff_requirements is not empty, due by the earliest expires_at there. pay_balance is required while a resolution waits for the buyer's payment. Example: []. */ "buyer_actions"?: never; /** RFC3339 timestamp. Format: date-time. */ "canceled_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "completed_at"?: string | globalThis.Date; "completed_by"?: ReturnActorInput; "completion_blockers": Array<ReturnCompletionBlockerInput>; "completion_mode"?: "manual" | "automatic"; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "customer_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "decision_at"?: string | globalThis.Date; "decision_status": "pending" | "approved" | "partially_approved" | "declined"; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "disposition_count": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "financial_summary": ReturnFinancialSummaryInput; "handoff_requirements": Array<ReturnHandoffRequirementInput>; "initiated_by": "buyer" | "merchant" | "integration" | "system"; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "inspection_count": string; "line_items": Array<ReturnLineItemInput>; "merchandise_status": "not_required" | "awaiting_handoff" | "in_transit" | "partially_received" | "received" | "inspection_required" | "partially_inspected" | "inspection_review_required" | "disposition_required" | "resolved" | "exception"; "metadata": Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed"; "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid"; "pricing_amounts": PricingAmountsInput; "refund_status": "none" | "partially_refunded" | "refunded"; "settlement_amounts": SettlementAmountsInput; "status": "open" | "closed"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "order_id": string; "policy_evaluation"?: ReturnPolicyEvaluationInput; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "receipt_count": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "resolution_count": string; "resolution_status": "not_selected" | "pending" | "partially_fulfilled" | "requires_action" | "fulfilled" | "failed"; "return_id": string; "return_number": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "shipment_count"?: string; "status": "requested" | "open" | "completed" | "declined" | "canceled"; "supported_actions": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string | globalThis.Date; /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "version": string; };
